def filter_components(components_in, threshold):
    kept = []
    for val, pos in components_in:
        rows = [p[0] for p in pos]
        cols = [p[1] for p in pos]
        min_r, max_r = min(rows), max(rows)
        min_c, max_c = min(cols), max(cols)
