def apply_rule(grid, bbox_threshold=5):
    bg = grid[0][0]
    from collections import deque

    visited = set()
    directions = [(0,1), (0,-1), (1,0), (-1,0)]

    # Find all components
    color_components = {}
    for r in range(len(grid)):
        for c in range(len(grid[r])):
            val = grid[r][c]
            if val != bg and (r,c) not in visited:
                comp_pos = []
                q = deque([(r,c)])
                while q:
                    cr, cc = q.popleft()
                    if (cr,cc) in visited: continue
                    visited.add((cr,cc))
                    comp_pos.append((cr,cc))

                    for dr, dc in directions:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < len(grid) and 0 <= nc < len(grid[nr]):
                            if grid[nr][nc] == val and (nr,nc) not in visited:
