                min_c, max_c = min(cols), max(cols)
                bbox_area = (max_r - min_r + 1) * (max_c - min_c + 1)

                color_components.setdefault(val, []).append({
                    'pos': comp_pos,
                    'bbox': (min_r, max_r, min_c, max_c),
                    'area': bbox_area
                })

    # Filter: keep colors with at least one component with bbox_area > threshold
    kept_colors = set()
    for val, comps in color_components.items():
        if any(c['area'] > bbox_threshold for c in comps):
